struct Node { int val; Node *left, *right; };

Node* buildRecursive(const std::vector<int>& v, int s, int e) {
	if (s > e) return nullptr;
	int m = s + (e - s) / 2;
	return new Node{v[m], buildRecursive(v, s, m - 1), buildRecursive(v, m + 1, e)};
}

Node* buildBalanced(const std::vector<int>& sorted) {
	return buildRecursive(sorted, 0, (int)sorted.size() - 1);
}
