std::vector<int> levelOrderIterative(Node* root) {
	std::vector<int> out;
	if (!root) return out;
	std::queue<Node*> q;
	q.push(root);
	while (!q.empty()) {
		Node* n = q.front();
		q.pop();
		out.push_back(n->val);
		if (n->left) q.push(n->left);
		if (n->right) q.push(n->right);
	}
	return out;
}
