struct Node { int val; Node *l, *r; };

int countNodesAtLevel(Node* root, int target) {
	if (!root) return 0;
	std::queue<Node*> q;
	q.push(root);
	int level = 0;
	while (!q.empty()) {
		int size = q.size();
		if (level == target) return size;
		for (int i = 0; i < size; ++i) {
			Node* n = q.front(); q.pop();
			if (n->l) q.push(n->l);
			if (n->r) q.push(n->r);
		}
		level++;
	}
